'use strict';
const AI=LoganAI;const expandedRounds=new Set();let historyExpanded=false;
let chatTimer=null,chatRunningIssue=null,attachmentTab='log',attachmentTask=null,attachmentMode='matched',inspectorTab='evidence',attachmentSelection=new Map(),draftHandoff=null;
const outcomes={pending:'待验证',supported:'人工记录支持',refuted:'人工记录反驳',inconclusive:'无法确定'};
function logEvidence(task,n){const t=tasks().find(t=>t.id===task),r=recordsForTask(t)[n];return {...evidenceMetadata(t,r),id:task+'-L'+n,kind:'log',index:n,task,label:'L'+(n+1)+' · '+r.module,text:r.time+' '+r.content};}
function investigation(i=issue()){
if(i.investigation)return i.investigation;
let a=i.analysis,s=i.investigation={rounds:[],context:[],hypotheses:[],revision:0,draft:'',task:currentTask()?.id||null};
if(a?.status==='done'){
(a.indices||[]).forEach(n=>AI.add(s,logEvidence(a.task,n)));(a.evidence||[]).forEach(e=>AI.add(s,e));
let r=AI.start(s,a.question||i.title);r.migrated=true;AI.finish(s,r.id);
}else i.evidence.forEach(e=>AI.add(s,e));save();return s;
}
function lastAnswer(s=investigation()){return s.rounds.filter(r=>r.status==='done').at(-1);}
function runningRound(s=investigation()){return s.rounds.find(r=>r.status==='running');}
function currentRevisionNote(s){let r=lastAnswer(s);return r&&r.revision!==s.revision?'<div class="notice context-changed">证据或验证结果已更新。旧回答保留当时范围，发送追问后再纳入新信息。</div>':'';}
function chatCitation(e,caption,roundId){return `<button class="citation" onclick="openChatEvidence('${e.id}','${roundId||''}')">${esc(caption||e.label)} <small>${esc(e.task)}</small></button>`;}
function reasoningView(r){
 const a=r.answer;if(!a?.facts)return '';
 const group=(title,items)=>items.length?`<section class="reasoning-group"><h4>${title}</h4>${items.map(c=>`<div class="reasoning-claim"><p>${esc(c.text)}</p><div class="citation-list">${c.evidenceIds.map(id=>r.snapshot.find(e=>e.id===id)).filter(Boolean).map(e=>chatCitation(e,null,r.id)).join('')}</div></div>`).join('')}</section>`:'';
 const d=a.delta,changes=d?.previous?`<details class="reasoning-delta" open><summary>相对 ${esc(d.previous)}：新增 ${d.added.length} · 更新 ${d.changed.length} · 移出 ${d.removed.length} 项证据 · 新增 ${d.verifications.length} 条验证</summary><div>${[...d.added,...d.changed].map(e=>chatCitation(e,null,r.id)).join('')}${d.removed.length?`<p>移出下轮范围：${d.removed.map(e=>esc(e.label)).join('、')}；原轮次快照仍保留。</p>`:''}</div></details>`:'';
 return `<div class="reasoning-proof">${changes}${group('事实 · 记录直接支持',a.facts)}${!a.facts.length?'<p class="muted">当前没有可用于本场景判断的直接事实。</p>':''}${group('推断 · 仍需验证',a.inferences)}${group('反证与冲突',a.conflicts)}</div>`;
}
function reasoningText(a){
 if(!a?.facts)return '';
 const label=e=>e.label+' / '+e.task+(e.kind==='source'?' / '+(e.match||'版本未确认'):'');
 const ref=id=>{const e=a.citations.find(e=>e.id===id);return e?label(e):id;};
 const section=(name,items)=>name+'：\n'+(items.map(c=>c.text+' [ '+c.evidenceIds.map(ref).join('、')+' ]').join('\n')||'无');
 return '\n\n'+[section('事实',a.facts),section('推断（未确认）',a.inferences),section('反证与冲突',a.conflicts)].join('\n\n')+
 (a.delta?.previous?`\n\n相对 ${a.delta.previous}：新增 ${a.delta.added.map(label).join('、')||'无'}；更新 ${a.delta.changed.map(label).join('、')||'无'}；移出 ${a.delta.removed.map(label).join('、')||'无'}；新增验证 ${a.delta.verifications.length} 条。`:'');
}
function roundView(r){let status={running:'正在整理',canceled:'已停止',interrupted:'刷新后已中断',done:'模拟回答'}[r.status];return `<article class="round" id="round-${r.id}"><div class="user-message"><div class="message-meta">你 · ${r.id} · ${esc(r.time)}${r.retryOf?' · 重试 '+r.retryOf:r.previous?' · 追问 '+r.previous:''}</div><p>${esc(r.question)}</p></div><div class="assistant-message"><div class="message-meta"><b>Logan 排查助手</b>${badge(status,r.status==='done'?'':'warn')}${r.migrated?'<small>沿用上一版分析范围</small>':''}</div><details class="scope-details"><summary>本轮范围：${r.snapshot.filter(e=>e.kind==='log').length} 条日志 · ${r.snapshot.filter(e=>e.kind==='source').length} 项源码 · ${r.verifications.length} 条验证记录</summary><p>本轮使用发送时的证据快照，后续补充不会改写此回答。</p><div class="citation-list">${r.snapshot.map(e=>chatCitation(e,null,r.id)).join('')||'<small>没有附加证据</small>'}</div></details>${r.status==='running'?`<div class="generating" role="status">${['读取本轮证据快照','对照上一轮与新增验证','整理回答及下一步'][Math.min(r.step,2)]}…</div>${btn('停止生成',`stopChat('${r.id}')`)}`:r.status==='done'?`<p>${esc(r.answer.body)}</p>${reasoningView(r)}${!r.answer.facts?'<div class="citation-list">'+r.answer.citations.map(e=>chatCitation(e,null,r.id)).join('')+'</div>':''}<div class="unknown"><b>仍待确认</b><p>${esc(r.answer.unknown)}</p></div><p><b>下一步：</b>${esc(r.answer.next)}</p><div class="toolbar compact">${btn('记录假设验证',"showHypotheses()")}${btn('基于此回答回写工单',`chatTicket('${r.id}')`,'primary')}${btn('继续追问',`suggestQuestion('这一步的证据是否充分？还缺什么？')`)}</div>`:`<p class="muted">${r.status==='interrupted'?'刷新中断了本轮模拟。':'已停止本轮生成。'}此前对话仍然保留，本轮不用于回写结论。</p>${btn('用原问题与快照重试',`retryChat('${r.id}')`,'',!!runningRound())}`}</div></article>`;}
function composer(){let s=investigation(),run=runningRound(s);return `<div class="composer panel"><div class="row"><h3>继续排查</h3>${badge('自然语言交互 · 本地模拟')}</div><div class="question-chips">${['为什么登录后一直转圈？','结合源码，哪些证据还不充分？','网络切换能解释超时吗？','下一步怎么验证这个假设？'].map(q=>btn(esc(q),`suggestQuestion('${q}')`,'chip',!!run)).join('')}</div><form id="chat-form" onsubmit="sendQuestion(event)"><label for="chat-question">你的问题或追问</label><textarea id="chat-question" ${run?'disabled':''} maxlength="1600" placeholder="例如：结合新补充的源码，失败分支是否解释了这次转圈？" oninput="investigation().draft=this.value;save()" onkeydown="if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();this.form.requestSubmit()}">${esc(s.draft||'')}</textarea><div id="chat-error" class="error" role="alert"></div><div class="toolbar"><button type="button" onclick="attachmentPicker('log')">＋ 日志证据</button><button type="button" onclick="attachmentPicker('source')">＋ 源码证据</button><small>本轮将引用 ${s.context.length} 项证据 · Enter 发送，Shift+Enter 换行</small><button class="primary" ${run?'disabled':''}>${run?'正在生成…':'发送问题'}</button></div></form><small>演示会按问题主题和所选证据生成预设回答，不执行代码，不访问设备或外部模型。</small></div>`;}
function evidencePanel(){let s=investigation();return `<div class="panel evidence-panel"><div class="row"><h3>本次调查证据 <small>${s.context.length} 项</small></h3>${btn('补充','attachmentPicker()')}</div><p class="muted">这里的证据用于下一次提问。旧轮次保留各自的快照。</p><div class="toolbar compact">${btn('补日志',"attachmentPicker('log')")}${btn('补源码',"attachmentPicker('source')")}${btn('回捞更多日志','collectForm()')}</div>${s.context.map(e=>`<div class="context-item"><div>${badge(e.kind==='source'?'源码':'日志')} ${chatCitation(e)}</div><p>${esc(e.text)}</p>${e.kind==='source'?`<small>${esc(e.match||'版本未知')}</small>`:''}<button class="textbutton remove-context" onclick="removeContext('${e.id}')">移出下轮范围</button></div>`).join('')||'<div class="empty">还没有证据。可以先提问澄清方向，也可补充此工单下的日志和源码。</div>'}</div>`;}
function hypothesesPanel(){let s=investigation();return `<div class="panel" id="hypotheses"><div class="row"><h3>假设与验证</h3>${badge('人工记录')}</div>${!s.hypotheses.length?'<p class="muted">当前证据尚不足以提出候选假设。先补足直接事实，再记录验证。</p>':s.hypotheses.map(h=>`<section class="hypothesis"><small>${h.id}</small><h4>${esc(h.title)}</h4>${badge(outcomes[h.status],h.status==='supported'?'ok':'warn')}${lastAnswer(s)?.answer.proposals&&!lastAnswer(s).answer.proposals.some(p=>p.id===h.id)?'<p class="notice">历史假设保留；当前轮证据不足以提出此假设，不应沿用为当前结论。</p>':''}<p class="muted">${h.id==='H1'?'检查失败后 loading 与 UI 是否实际恢复。':'检查网络切换与超时是否有可重复的因果关系。'}</p>${h.history.length?`<details><summary>${h.history.length} 条验证记录 · 最新：${esc(h.history.at(-1).time)}</summary>${h.history.map(v=>`<div class="verification-record"><b>${outcomes[v.outcome]}</b><p>步骤：${esc(v.method)}<br>观察：${esc(v.observation)}</p><small>${esc(v.time)} · 引用 ${v.evidenceIds?.length||0} 项证据</small></div>`).join('')}</details>`:''}<div class="toolbar compact">${btn(h.history.length?'补充验证记录':'记录验证结果',`verifyHypothesis('${h.id}')`)}</div></section>`).join('')}</div>`;}
views.report=function(){let s=investigation(),done=lastAnswer(s),run=runningRound(s);return heading('AI 排查工作台','围绕同一个问题持续追问、补证与验证，最后将调查记录回写工单。')+breadcrumbs()+flow()+`<div class="toolbar">${btn('补充日志证据',"attachmentPicker('log')")}${btn('补充源码证据',"attachmentPicker('source')")}${btn('粘贴日志 / 源码片段','pasteEvidence()')}${btn('假设与验证','showHypotheses()')}${btn('生成工单更新草稿','chatTicket()','primary',!done||!!run)}${btn('导出对话与调查','exportConversation()','',!s.rounds.length)}</div><div class="notice">此处是交互原型：回答采用预设场景和规则模拟。验证结果由你记录；系统没有实际复现或确认真实根因。</div>${currentRevisionNote(s)}<div class="investigation-grid"><div class="conversation-column"><div class="conversation-heading"><h3>调查对话</h3><small>${s.rounds.length} 轮 · ${s.rounds.at(-1)?.id||'尚未开始'} · 保留证据快照</small></div><div id="conversation">${conversationMarkup(s)||`<div class="panel empty"><h3>先描述你要排查的问题</h3><p>可以直接提问，也可以先补充日志和源码。没有证据时会明确提示信息不足。</p></div>`}</div>${composer()}</div><div class="investigation-sidebar"><div class="inspector-tabs">${btn('证据范围 '+s.context.length,"inspectorTab='evidence';render()",inspectorTab==='evidence'?'primary':'')}${btn('假设验证 '+s.hypotheses.length,"inspectorTab='hypotheses';render()",inspectorTab==='hypotheses'?'primary':'')}</div>${inspectorTab==='evidence'?evidencePanel():hypothesesPanel()}</div></div>`;};
function suggestQuestion(q){let s=investigation();s.draft=q;save();if(page!=='report')go('report');else render();$('#chat-question')?.focus();$('#chat-question')?.scrollIntoView({block:'center',behavior:'auto'});}
function sendQuestion(event){event?.preventDefault();if(chatRunningIssue&&chatRunningIssue!==issue().id)return toast('另一工单正在生成，请等待本地模拟完成后提问');let input=$('#chat-question'),q=input?.value||investigation().draft;try{let r=AI.start(investigation(),q);investigation().draft='';save();startChatTimer(issue().id,r.id);render();$('#round-'+r.id)?.scrollIntoView({block:'start',behavior:'auto'});}catch(e){if($('#chat-error'))$('#chat-error').textContent=e.message;else toast(e.message);}}
function startChatTimer(issueId,roundId){if(chatTimer)clearInterval(chatTimer);chatRunningIssue=issueId;chatTimer=setInterval(()=>{let i=state.issues.find(x=>x.id===issueId),s=i?.investigation,r=s?.rounds.find(r=>r.id===roundId);if(!r||r.status!=='running'){clearInterval(chatTimer);chatTimer=null;chatRunningIssue=null;return;}r.step++;if(r.step>=3){AI.finish(s,r.id);clearInterval(chatTimer);chatTimer=null;chatRunningIssue=null;}save();if(state.active===issueId&&(page==='report'||(page==='workbench'&&workUI.issueMode==='chat')))render();},650);}
function stopChat(id){AI.stop(investigation(),id);if(chatRunningIssue===issue().id&&chatTimer){clearInterval(chatTimer);chatTimer=null;chatRunningIssue=null;}save();render();}
function retryChat(id){let s=investigation(),old=s.rounds.find(r=>r.id===id);try{let r=AI.start(s,old.question);r.snapshot=JSON.parse(JSON.stringify(old.snapshot));r.verifications=JSON.parse(JSON.stringify(old.verifications));r.revision=old.revision;r.previous=old.previous;r.previousSnapshot=JSON.parse(JSON.stringify(old.previousSnapshot||[]));r.previousVerifications=JSON.parse(JSON.stringify(old.previousVerifications||[]));r.retryOf=old.id;save();startChatTimer(issue().id,r.id);render();}catch(e){toast(e.message);}}
analysisForm=function(){go('report');if(!investigation().draft)investigation().draft=issue().title+'，请先整理已有证据与缺失信息。';save();render();$('#chat-question')?.focus();};
addEvidence=function(e){let i=issue(),s=investigation();if(!i.evidence.some(x=>x.id===e.id))i.evidence.push({...e});let added=AI.add(s,e);save();render();toast(added?'已补充到调查，下次提问会引用新证据':'该证据已在调查范围内');};
function removeContext(id){let s=investigation();s.context=s.context.filter(e=>e.id!==id);s.revision++;save();render();}
function findChatEvidence(id,roundId){let s=investigation();if(roundId)return s.rounds.find(r=>r.id===roundId)?.snapshot.find(x=>x.id===id);return s.context.find(x=>x.id===id)||s.rounds.flatMap(r=>r.snapshot).find(x=>x.id===id);}
function openChatEvidence(id,roundId){let e=findChatEvidence(id,roundId);if(!e)return toast('未找到证据');openModal('证据快照 · '+esc(e.label),`<p>${esc(e.task)} · ${e.kind==='log'?'日志事件':'源码位置'}${e.kind==='source'?' · '+esc(e.match):''}</p><div class="code">${esc(e.text)}</div><p class="muted">设备 ${esc(e.device||'未记录')} · ${esc(e.platform||'平台未记录')} · 版本 ${esc(e.version||'未记录')} / 构建 ${esc(e.build||'未记录')}<br>日期 ${esc(e.day||'未记录')} · requestId ${esc(e.requestId||String(e.text).match(/requestId=([^;\s]+)/)?.[1]||'未记录')}<br>${e.versionOrigin==='issue-hint'?'版本来自工单线索，未保存采集时快照。':''}</p>${e.kind==='source'?`<p class="muted">${esc(e.file||'未记录源码路径')}${e.line?':'+esc(e.line):''} · 构建 ${esc(e.build||'快照未记录')} · ${esc(e.commit||'未记录提交')}</p>`:''}<div class="toolbar">${e.manual?'':btn('前往原始位置',`openOriginalEvidence('${e.id}','${roundId||''}')`,'primary')}${btn('返回对话','closeModal()')}</div><small>这是该证据被引用时保存的快照，后续移出上下文不会删除历史引用。</small>`);}
function openOriginalEvidence(id,roundId){let e=findChatEvidence(id,roundId);if(e.manual)return toast('这是一份手动粘贴的本地快照，未连接外部原始位置');if(!tasks().some(t=>t.id===e.task))return toast('原任务当前不可用，仍可阅读已保存快照');closeModal();taskId=e.task;selected=e.index;query='';level='全部';contextMode=false;sourceMode=e.mode||'matched';go(e.kind==='source'?'source':'logs');}
function attachmentPicker(tab='log'){attachmentTab=tab;attachmentTask=currentTask()?.id||tasks()[0]?.id;attachmentSelection=new Map();renderAttachments();}
function attachmentCandidates(){let t=tasks().find(t=>t.id===attachmentTask);if(!t)return [];return availableIndices(t).map(n=>{if(attachmentTab==='log')return logEvidence(t.id,n);let r=recordsForTask(t)[n],mode=r.file&&r.sourceVerified!==false&&t.version&&t.build?attachmentMode:'candidate';return {...evidenceMetadata(t,r),id:t.id+'-S'+n+'-'+mode,kind:'source',index:n,task:t.id,label:'S'+(n+1)+' · '+(r.file||'模块候选'),text:code(r).replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&'),mode,match:mode==='matched'?'演示：构建版本匹配':'关键词候选 · 尚未验证版本',file:r.file||null,build:t.build||issue().build,commit:mode==='matched'?'demo-c81（虚构提交）':'未知'};});}
function renderAttachments(){let s=investigation(),candidates=attachmentCandidates();openModal('补充调查证据',`<div class="tabs">${btn('日志证据',"attachmentTab='log';renderAttachments()",attachmentTab==='log'?'primary':'')}${btn('源码证据',"attachmentTab='source';renderAttachments()",attachmentTab==='source'?'primary':'')}</div>${tasks().length?`<label for="attach-task">此工单的日志任务</label><select id="attach-task" onchange="attachmentTask=this.value;renderAttachments()">${tasks().map(t=>`<option value="${t.id}" ${t.id===attachmentTask?'selected':''}>${t.id}${t.partial?' · 部分文件可用':''}</option>`).join('')}</select>${attachmentTab==='source'?`<label for="attach-mode">源码匹配依据</label><select id="attach-mode" onchange="attachmentMode=this.value;renderAttachments()"><option value="matched" ${attachmentMode==='matched'?'selected':''}>演示：构建版本匹配</option><option value="candidate" ${attachmentMode==='candidate'?'selected':''}>仅关键词候选 · 尚未验证</option></select><p class="muted">文件与提交均为虚构样例。无文件行号的日志只能关联到候选源码。</p>`:'<p class="muted">只列出已解析文件对应的事件，不包含上传失败文件。</p>'}<div class="attachment-list">${candidates.map((e,n)=>{let included=s.context.some(x=>x.id===e.id);return `<label class="attachment-choice"><input type="checkbox" aria-label="选择 ${esc(e.label)}" ${included?'checked disabled':attachmentSelection.has(e.id)?'checked':''} onchange="toggleAttachment(${n},this.checked)"><span><b>${esc(e.label)}</b> ${included?badge('已在范围内'):''}<small>${esc(e.task)}${e.kind==='source'?' · '+esc(e.match):''}</small><p>${esc(e.text.slice(0,180))}</p></span></label>`;}).join('')}</div><div class="toolbar">${btn('加入下轮分析','applyAttachments()','primary')}${btn('取消','closeModal()')}<small id="attachment-count">已选择 ${attachmentSelection.size} 项</small></div>`:`<div class="empty"><h3>还没有可查日志</h3><p>先从工单发起回捞，解析完成后即可补充证据。</p>${btn('发起回捞','collectForm()','primary')}</div>`}<small>新增证据只影响下一轮提问，不会重写过去的回答。</small>`,true);}
function toggleAttachment(n,checked){let e=attachmentCandidates()[n];if(checked)attachmentSelection.set(e.id,e);else attachmentSelection.delete(e.id);$('#attachment-count').textContent='已选择 '+attachmentSelection.size+' 项';}
function applyAttachments(){if(!attachmentSelection.size)return toast('先选择要补充的证据');let s=investigation(),count=0;attachmentSelection.forEach(e=>{if(AI.add(s,e))count++;if(!issue().evidence.some(x=>x.id===e.id))issue().evidence.push({...e});});save();closeModal();go('report');toast('已补充 '+count+' 项证据；发送追问后纳入分析');}
function showHypotheses(){inspectorTab='hypotheses';go('report');$('#hypotheses')?.scrollIntoView({block:'start',behavior:'auto'});}
function verifyHypothesis(id){let s=investigation(),h=s.hypotheses.find(h=>h.id===id);openModal('验证假设 · '+id,`<p><b>${esc(h.title)}</b></p><form onsubmit="saveVerification(event,'${id}')"><label for="verify-method">验证步骤与环境 *</label><textarea id="verify-method" required placeholder="例如：在 3.8.1 build 38107 模拟登录超时，观察 loading 和 UI 状态"></textarea><label for="verify-observation">实际观察 *</label><textarea id="verify-observation" required placeholder="记录实际发生了什么，而不只写支持或不支持"></textarea><label for="verify-outcome">验证结论</label><select id="verify-outcome"><option value="inconclusive">无法确定，需要更多信息</option><option value="supported">支持此假设</option><option value="refuted">反驳此假设</option></select><label>关联证据（可选）</label><div class="verify-evidence">${s.context.map(e=>`<label class="check"><input name="verify-evidence" type="checkbox" value="${e.id}">${esc(e.label)} · ${esc(e.task)}</label>`).join('')||'<small>当前没有附加证据，仍可保存人工观察。</small>'}</div><p class="notice">这里保存的是人工填写的模拟验证记录，系统不会执行复现或自动确认根因。</p><p id="verification-error" class="error" role="alert"></p><div class="toolbar"><button class="primary">保存验证记录</button><button type="button" onclick="closeModal()">取消</button></div></form>`,true);}
function saveVerification(e,id){e.preventDefault();try{AI.verify(investigation(),id,{method:$('#verify-method').value,observation:$('#verify-observation').value,outcome:$('#verify-outcome').value,evidenceIds:[...document.querySelectorAll('input[name="verify-evidence"]:checked')].map(x=>x.value)});save();closeModal();inspectorTab='hypotheses';render();toast('已保存验证结果。可追问“结合新的验证结果继续排查”');}catch(err){$('#verification-error').textContent=err.message;}}
function handoffText(h){let supported=h.hypotheses.filter(x=>x.status==='supported'),refuted=h.hypotheses.filter(x=>x.status==='refuted'),pending=h.hypotheses.filter(x=>['pending','inconclusive'].includes(x.status));return `问题：${issue().title}\n引用轮次：${h.round} · ${h.question}\n\n本轮回答（生成时范围）：\n${h.body}${reasoningText(h.reasoning)}\n\n最新人工验证：\n${h.verifications.map(v=>`${v.hypothesis} ${outcomes[v.outcome]}；步骤：${v.method}；观察：${v.observation}`).join('\n')||'尚无验证记录'}\n\n本轮检验方向：${h.reasoning?.proposals?.map(p=>p.id+' '+p.title).join('；')||'未形成可支持的方向'}\n假设记录（含历史，以下状态为人工记录）：\n支持：${supported.map(x=>x.title).join('；')||'无'}\n反驳：${refuted.map(x=>x.title).join('；')||'无'}\n待确认：${pending.map(x=>x.title).join('；')||'无'}\n\n未知项：${h.unknown}\n下一步：${h.next}\n\n证据：${h.evidence.map(e=>e.label+' / '+e.task+(e.kind==='source'?' / '+e.match:'')).join('；')||'无'}\n\n所有日志、源码、回答及验证均为交互演示，不代表真实根因。`;}
function chatTicket(roundId){let s=investigation(),r=roundId?s.rounds.find(x=>x.id===roundId):lastAnswer(s);try{draftHandoff=AI.handoff(s,r?.id);}catch(e){return toast(e.message);}let h=draftHandoff,i=issue();openModal('回写工单 · '+esc(i.id),`<form onsubmit="saveChatTicket(event)"><div class="handoff-flow">对话 ${h.round} → ${h.evidence.length} 项证据 → ${h.verifications.length} 条验证 → 工单草稿</div>${h.revision!==h.answerRevision?'<div class="notice">本轮回答之后又增加了证据或验证。草稿同时保留旧回答与最新验证，请检查是否冲突；也可以先继续追问再回写。</div>':''}<div class="form-grid"><div><label for="chat-ticket-status">工单状态</label><select id="chat-ticket-status">${['调查中','待修复','待验证','已解决'].map(x=>`<option ${i.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label for="chat-ticket-owner">负责人 *</label><input id="chat-ticket-owner" required value="${esc(i.owner==='待分配'?'':i.owner)}" placeholder="填写处理负责人"></div></div><label for="chat-ticket-summary">可编辑的调查结果 *</label><textarea id="chat-ticket-summary" class="long" required>${esc(handoffText(h))}</textarea><details><summary>检查将附带的证据和验证记录</summary><div class="citation-list">${h.evidence.map(e=>`<span class="badge">${esc(e.label)} / ${esc(e.task)}</span>`).join('')}</div><p>${h.verifications.map(v=>esc(v.hypothesis+' · '+outcomes[v.outcome]+' · '+v.observation)).join('<br>')||'无人工验证记录'}</p></details><label class="check"><input id="chat-ticket-confirm" type="checkbox">我已核对事实、推断、验证记录与未知项</label><label class="check"><input id="chat-ticket-resolved" type="checkbox">本次问题已经完成复现与修复验证（模拟记录）</label><p id="chat-ticket-error" class="error" role="alert"></p><div class="toolbar"><button class="primary">保存到本地工单</button><button type="button" onclick="closeModal()">返回继续排查</button></div><small>只回写此浏览器的工单，不发送消息、不修改真实源码。</small></form>`,true);}
ticket=function(){chatTicket();};
function saveChatTicket(e){e.preventDefault();let err=$('#chat-ticket-error'),status=$('#chat-ticket-status').value,owner=$('#chat-ticket-owner').value.trim(),text=$('#chat-ticket-summary').value.trim();if(!owner||!text){err.textContent='请填写负责人和调查结果。';return;}if(!$('#chat-ticket-confirm').checked){err.textContent='请先核对事实、推断、验证记录与未知项。';return;}if(status==='已解决'&&(!$('#chat-ticket-resolved').checked||!draftHandoff.verifications.length)){err.textContent='标记已解决需要至少一条验证记录，并确认已完成复现与修复验证；可先保存为待验证。';return;}let i=issue(),h=JSON.parse(JSON.stringify(draftHandoff));i.owner=owner;i.status=status;i.verified=$('#chat-ticket-resolved').checked;i.updates.unshift({time:new Date().toLocaleString('zh-CN'),status,owner,verified:i.verified,summary:text,evidence:h.evidence.map(e=>e.label+' / '+e.task),investigation:h});delete i.handoffDraft;save();closeModal();issueDetail=true;go('issues');toast('对话结论、证据快照、验证记录和工单状态已一并保存');}
function exportConversation(){let s=investigation(),r=lastAnswer(s);file(issue().id+'-ai-investigation-demo.txt',(r?handoffText(AI.handoff(s,r.id)):'暂无完成回答')+'\n\n完整对话\n'+s.rounds.map(r=>`${r.id} ${r.status}\n问题：${r.question}\n${r.answer?.body||'本轮未完成'}\n范围：${r.snapshot.map(e=>e.label+' / '+e.task).join('；')}`).join('\n\n'));}
downloadReport=exportConversation;
for(const i of state.issues){for(const r of i.investigation?.rounds||[])if(r.status==='running')r.status='interrupted';}save();render();
function pasteEvidence(){openModal('粘贴日志或源码片段',`<form onsubmit="savePastedEvidence(event)"><label for="paste-kind">材料类型</label><select id="paste-kind"><option value="log">日志片段</option><option value="source">源码片段</option></select><label for="paste-title">材料名称 *</label><input id="paste-title" required maxlength="80" placeholder="例如：超时后的 UI 状态日志"><label for="paste-origin">来源 / 文件位置</label><input id="paste-origin" maxlength="160" placeholder="例如：LoginViewModel.swift:118 或本地复现记录"><label for="paste-body">片段内容 *</label><textarea id="paste-body" class="long" maxlength="12000" required placeholder="粘贴补充材料，仅保存在此浏览器"></textarea><p class="notice">手动片段默认未验证来源和版本。此原型只演示携带与引用，不会自动理解任意代码或日志，也不会把片段当作可执行指令。</p><p id="paste-error" class="error" role="alert"></p><div class="toolbar"><button class="primary">加入下轮分析</button><button type="button" onclick="closeModal()">取消</button></div></form>`,true);}
function savePastedEvidence(event){event.preventDefault();let title=$('#paste-title').value.trim(),body=$('#paste-body').value.trim();if(!title||!body){$('#paste-error').textContent='请填写材料名称和片段内容。';return;}let s=investigation();s.manualSeq=(s.manualSeq||0)+1;let e={id:'MANUAL-'+issue().id+'-'+s.manualSeq,kind:$('#paste-kind').value,task:'人工补充 · '+issue().id,index:null,label:'M'+s.manualSeq+' · '+title,text:body,manual:true,file:$('#paste-origin').value.trim()||'未记录来源',build:'未验证',commit:'未验证',mode:'unverified',match:'人工片段 · 来源与版本未验证'};AI.add(s,e);issue().evidence.push({...e});save();closeModal();inspectorTab='evidence';go('report');toast('片段已加入下轮范围；不会改变已有回答');}

function conversationMarkup(s){let older=s.rounds.slice(0,-1),latest=s.rounds.at(-1);return (older.length?`<details class="conversation-history" ${historyExpanded?'open':''} ontoggle="historyExpanded=this.open"><summary>查看此前 ${older.length} 轮对话 <small>保留旧回答、已停止与已中断的轮次</small></summary>${older.map(r=>`<details class="archived-round" ${expandedRounds.has(r.id)?'open':''} ontoggle="this.open?expandedRounds.add('${r.id}'):expandedRounds.delete('${r.id}')"><summary>${esc(r.id+' · '+r.question.slice(0,64))}</summary>${roundView(r)}</details>`).join('')}</details>`:'')+(latest?roundView(latest):'');}
